{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "거래처 데이터에서 얻은 판단을 캠페인의 우선 접촉 대상 선정 기준으로 연결할 수 있는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "오름퍼니처에서 휴면 거래처 재접촉 캠페인을 진행한 상황",
          "task": "거래처별 발주 내역을 바탕으로 먼저 연락할 대상을 정하는 일",
          "action": "우선 접촉 대상을 가르는 데 사용한 기준을 실제 거래처 상태와 연결해 설명",
          "result": "그 기준에 따라 어떤 거래처가 우선 대상이 되었는지 정리"
        },
        "expectedEvidence": [
          "먼저 연락할 거래처를 정하는 데 실제로 사용한 판단 기준",
          "그 기준을 판단하는 데 살펴본 거래처별 발주 정보",
          "우선 대상과 나머지 대상을 구분한 구체적인 거래처 상태"
        ]
      },
      "question": "오름퍼니처의 휴면 거래처 재접촉 캠페인에서, 먼저 연락할 거래처를 정하는 데 가장 중요하게 본 기준은 무엇이었나요?",
      "answerTip": "당시의 구체적인 장면을 떠올리며 본인이 한 일을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "발주 품목과 시기를 확인했다는 설명에 그치지 않고, 어떤 상태의 거래처를 먼저 연락할 대상으로 판단했는지 구체적인 선정 기준을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "재주문 가능성이 높은 거래처부터 연락한다는 일반적인 기준은 제시하지만, 실제 발주 정보에서 우선 대상을 구분한 기준은 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "휴면 거래처의 우선 접촉 기준을 제시하지 못하거나, 재주문 성과 등 대상 선정과 다른 이야기만 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "광고 반응 비교를 통해 내린 소재 변경 판단을 비전문가가 이해할 수 있는 성과 해석으로 설명할 수 있는지 확인한다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "광고를 잘 모르는 동료에게 꽃집 인스타그램 광고의 소재 변경 판단을 설명하는 상황",
          "task": "가격 표기형으로 광고 소재를 바꾼 이유를 이해하기 쉽게 전달하는 일",
          "action": "실제로 비교한 광고 반응을 바탕으로 소재 변경 판단을 쉬운 말로 설명",
          "result": "동료가 어떤 광고 반응을 보고 소재를 바꿨는지 이해할 것으로 예상"
        },
        "expectedEvidence": [
          "가격 표기형으로 소재를 바꾼 판단을 동료에게 전달할 실제 설명",
          "그 설명에 사용한 게시물 유형별 반응의 구체적인 비교",
          "비교한 반응이 소재 변경 판단으로 이어지는 연결"
        ]
      },
      "question": "꽃집 인스타그램 광고에서 가격 표기형으로 소재를 바꾼 판단을 광고를 잘 모르는 동료에게 설명한다면, 어떤 말로 설명하시겠어요?",
      "answerTip": "상대에게 직접 말하듯 짧고 자연스러운 문장으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "가격 표기형의 문의가 많았다는 지원서 표현을 반복하는 데 그치지 않고, 실제 비교한 반응의 차이를 구체적으로 짚어 광고 소재 변경 판단을 쉬운 말로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "반응이 좋은 광고 소재에 집중했다는 취지는 전달하지만, 꽃집 광고에서 비교한 반응이나 그 해석은 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "광고 소재를 바꾼 판단에 대한 설명이 없거나, 광고 집행 이력 등 다른 이야기만 한다."
          ]
        }
      }
    }
  ]
}
